# Account operations.
from ledger.errors import InsufficientFunds


def withdraw(balance_cents, amount_cents):
    if amount_cents == 0:
        raise ValueError('amount must be positive')
    if amount_cents > balance_cents:
        raise InsufficientFunds()
    return balance_cents - amount_cents

files.tests/test_account.py:
import unittest

from ledger.account import withdraw
from ledger.errors import InsufficientFunds


class WithdrawTest(unittest.TestCase):
    def test_returns_balance_after_withdrawal(self):
        self.assertEqual(withdraw(10000, 2500), 7500)

    def test_amount_above_balance_raises(self):
        with self.assertRaises(InsufficientFunds):
            withdraw(100, 101)

    def test_amount_equal_to_balance_returns_zero(self):
        self.assertEqual(withdraw(100, 100), 0)

    def test_zero_amount_raises_value_error(self):
        with self.assertRaises(ValueError):
            withdraw(100, 0)


if __name__ == '__main__':
    unittest.main()

